cat > .local/smart-shorts-seven/extract-size-probe.mjs <<'EOF'
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import * as glue from '../../classic/rust/editor-runtime-wasm/pkg/opencut_editor_runtime_wasm_bg.js';
const bytes=await readFile(new URL('../../classic/rust/editor-runtime-wasm/pkg/opencut_editor_runtime_wasm_bg.wasm',import.meta.url));
const {instance}=await WebAssembly.instantiate(bytes,{'./opencut_editor_runtime_wasm_bg.js':glue});glue.__wbg_set_wasm(instance.exports);instance.exports.__wbindgen_start();
const project=JSON.parse(await readFile(new URL('./project-transcribed-before-shorts.json',import.meta.url)));
const id=project.metadata.id;let runtime=new glue.CanonicalEditorRuntime();
const call=(cap,input)=>runtime.invokeSync(cap,input,{}).result.data;
call('project.classic.session.restore',{projectId:id,expectedRevision:0,archive:JSON.parse(project.__opencutEditorSession).saved.bundle.archive});
const before=runtime.snapshot().project.classic;const main=before.document.scenes.find(s=>s.isMain);
const base={projectId:id,sceneId:main.id,elementIds:main.tracks.main.elements.filter(e=>e.type==='video').map(e=>e.id),expectedRevision:runtime.snapshot().revision};
const prepared=call('timeline.classic.podcast.prepare',base);
const words=prepared.words;
const videos=Array.from({length:7},(_,i)=>{const first=words.findIndex(w=>w.start>=i*600*120000+10*120000);let last=first;while(last+1<words.length && words[last].end-words[first].start<25*120000)last++;return {title:'Isolated size test '+i,openingHook:'Test',endingHook:'Test',confidence:.9,alternatives:[{label:'Test',reason:'Isolated storage check',parts:[{firstWord:first,lastWord:last}]}]}});
call('timeline.classic.podcast.extract',{...base,options:{mode:'highlights',minSeconds:20,maxSeconds:90,maxOutputs:7},videos});
const after=runtime.snapshot().project.classic;assert.equal(after.document.scenes.length,8);assert.deepEqual(after.document.scenes.find(s=>s.isMain),main);
